text:
{
  "jobs": [
    {
      "text": "Экстренно останавливать мошенников, когда близкие уже диктуют коды или переводят деньги",
      "quote": "В тот раз соседка физически выдернула телефон из рук бабушки, потому что та уже диктовала код из СМС — это был не совет, а экстренная остановка кражи."
    },
    {
      "text": "Объяснять родителям технические детали и безопасность простым языком",
      "quote": "привыкла скидывать мне скрины странных СМС с кодами от Госуслуг, которые я ей потом объясняю, как для чайников."
    },
    {
      "text": "Физически забирать телефон у родителя во время подозрительного звонка",
      "quote": "Я тогда только нажала кнопку отбоя... В итоге я просто забрала у неё телефон, пока она не успела отправить этот код по SMS на неизвестный номер."
    },
    {
      "text": "Ручное управление настройками безопасности в личных кабинетах операторов за родителей",
      "quote": "Сейчас я периодически захожу в личный кабинет оператора и вручную добавляю черные списки"
    }
  ],
  "pains": [
    {
      "text": "Чувство бессилия перед абстрактностью предупреждений для пожилых людей",
      "quote": "для 88-летней женщины с кнопочным телефоном фраза «это мошенники» звучит абстрактно, а конкретное вмешательство и блокировка номера — единственный работающий инструмент."
    },
    {
      "text": "Паника родителей перекрывает логику, заставляя их выполнять инструкции мошенников",
      "quote": "Она чуть не заплакала, потому что реально испугалась за деньги и начала искать в телефоне приложение банка под диктовку звонящего."
    },
    {
      "text": "Бесполезность официальных жалоб в банки и операторов",
      "quote": "позвонила в банк и написала жалобу на мошенников, но толку от этого, как от козла молока — мне просто сказали «спасибо за обращение»."
    },
    {
      "text": "Невозможность защитить близких от звонков через мессенджеры (WhatsApp)",
      "quote": "Звонили через WhatsApp, а не по мобильной сети, поэтому все наши телефонные фильтры были абсолютно бесполезны и молчали как партизаны."
    },
    {
      "text": "Страх ложных срабатываний фильтров, блокирующих важные звонки (врач, работа)",
      "quote": "вдруг отрубят звонок из больницы или от моего начальника? ... Самый страшный момент — когда ты понимаешь, что потеряла возможность вовремя среагировать"
    }
  ],
  "current_solutions": [
    {
      "text": "Установка сторонних блокировщиков спама на телефоны родителей",
      "quote": "Я поставила на телефоны мамы и бабушки блокировщик спама"
    },
    {
      "text": "Использование функции «черный список» в личном кабинете оператора",
      "quote": "вручную добавляю черные списки, хотя это костыль, а не решение."
    },
    {
      "text": "Отключение входящих вызовов через приложение оператора при атаке",
      "quote": "я отключила все входящие вызовы на её номере через приложение оператора"
    },
    {
      "text": "Личное присутствие и физический контроль телефона во время звонков",
      "quote": "Пришлось экстренно вмешаться, отобрать телефон и звонить в поддержку оператора"
    }
  ],
  "barriers": [
    {
      "text": "Барьер понимания: страх, что алгоритм ошибется и заблокирует важный контакт",
      "quote": "непонятно, кто решает, что это мошенник: вдруг отрубят звонок из больницы или от моего начальника?"
    },
    {
      "text": "Барьер выбора/использования: необходимость постоянно проверять уведомления о блокировках",
      "quote": "Если мне нужно будет постоянно проверять уве[АДРЕС]«почему мы отбили этот звонок», чтобы убедиться, что это не врач или не срочный рабочий вопрос, то услуга только добавит мне головной боли вместо её снятия."
    },
    {
      "text": "Барьер оплаты: убежденность, что базовая защита должна быть бесплатной обязанностью провайдера",
      "quote": "Никогда не платила за «анти-спам» или защиту номера, считая это базовой обязанностью оператора, а не доп-услугой для извлечения денег."
    },
    {
      "text": "Технический барьер: разные операторы в семье требуют отдельной настройки каждого аккаунта",
      "quote": "у нас разные операторы, и я боюсь, что эти фильтры будут работать криво или требовать отдельной настройки на каж[АДРЕС]а я уже устала разбираться с чужими личными кабинетами."
    }
  ],
  "triggers": [
    {
      "text": "Реальный случай потери денег или попытки кражи у близкого человека",
      "quote": "Бабушке звонили «внук попал в ДТП», спасла соседка."
    },
    {
      "text": "Момент, когда родитель начинает диктовать коды из СМС мошеннику",
      "quote": "она уже начала диктовать коды из СМС, которые ей приходили в реальном времени."
    },
    {
      "text": "Ощущение, что текущие инструменты защиты не справляются с новыми схемами (маскировка под банк)",
      "quote": "блокировщик определил как «Возможный спам», но не заблокировал полностью. Она ответила, потому что на экране высветилось название банка"
    }
  ],
  "words": [
    "костыль",
    "как для чайников",
    "экстренная остановка кражи",
    "классический скрипт",
    "как от козла молока",
    "молчали как партизаны",
    "до боли реалистично",
    "играл в «угадайку»",
    "нервный срыв",
    "выдохнуть"
  ],
  "surprises": [
    "Респондент отказывается использовать даже существующие умные фильтры не из-за цены, а из-за страха ложных срабатываний, которые могут привести к потере важного контакта (врач/работа).",
    "Основной триггер для действий — не теоретическая опасность, а физическое вмешательство (отобрать телефон), так как вербальные советы игнорируются из-за паники.",
    "Защита через мессенджеры (WhatsApp) воспринимается как полная дыра в безопасности, которую невозможно закрыть стандартными средствами оператора.",
    "Готовность платить существует только за сервисы, которые *экономят* время (музыка, интернет), а не за те, которые добавляют рутину по проверке уведомлений о блокировках."
  ]
}
